use vstd::prelude::*;

verus! {
    fn ones_like<T>(a: &Vec<T>) -> (result: Vec<i32>)
        ensures
            result.len() == a.len(),
            forall|i: usize| (i < a.len() ==> result[i] == 1),
    {
        let mut result: Vec<i32> = Vec::new();

        let len = a.len();

        let mut i: usize = 0;
        while i < len
            invariant i <= len,
            invariant result.len() == i,
            invariant forall|j: usize| (j < i ==> result[j] == 1),
            decreases len - i,
        {
            result.push(1);
            i = i + 1;
        }

        result
    }
}
